import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Анимированные GIF — самые тяжёлые изображения в интернете. Десятисекундный ролик может весить 20 МБ — больше, чем целая страница фотографий.</p>\n<p>Сжатие GIF отличается от сжатия фото. У GIF есть кадры, палитры и тайминги, и каждый из них даёт способ уменьшить файл.</p>\n<p>Это руководство объясняет, как работает сжатие GIF, какие пресеты выбрать и как получить маленький файл без потери анимации. Сжать свой GIF без потери анимации можно в инструменте <a href=\"/ru/szhat-gif/\">Компрессор GIF</a>: он урезает палитру, кадры и размеры, сохраняя движение.</p>\n<h2 id=\"why-gifs-are-big\">Почему GIF такие большие</h2>\n<p>GIF — это флипбук. Он хранит десятки или сотни кадров, и каждый кадр — это отдельное изображение.</p>\n<p>Десятисекундный GIF при 15 кадрах в секунду содержит 150 кадров. Даже маленькие кадры быстро складываются, когда их так много.</p>\n<p>Сжатие GIF — это старая технология. Формат появился в 1987 году, и он хранит каждый кадр с ограниченной палитрой в 256 цветов.</p>\n<p>Современные видеоформаты вроде MP4 сжимают намного лучше. Ролик, который весит 20 МБ как GIF, может весить 2 МБ как MP4.</p>\n<h2 id=\"how-gif-compression-works\">Как работает сжатие GIF</h2>\n<p>Компрессор GIF атакует размер файла с четырёх сторон: цветовая палитра, число кадров, частота кадров и размеры изображения.</p>\n<p>Уменьшение палитры с 256 цветов до 128 или 64 сокращает данные на кадр. Фотографические GIF страдают сильнее, чем плоская графика.</p>\n<p>Удаление кадров уменьшает их общее число. Удаление каждого второго кадра вдвое сокращает кадры, сохраняя тайминг естественным.</p>\n<p>Уменьшение размеров сжимает каждый кадр сразу. GIF вдвое меньшей ширины и высоты содержит вчетверо меньше пикселей.</p>\n<h2 id=\"presets-explained\">Пресеты: объяснение</h2>\n<p>«Лёгкий» применяет мягкое сжатие. Он слегка урезает палитру и сохраняет анимацию плавной — это подходит для GIF, которые должны оставаться красивыми.</p>\n<p>«Сбалансированный» — пресет по умолчанию. Он уменьшает палитру, обрезает часть кадров и разумно масштабирует, давая хорошую середину для большинства GIF.</p>\n<p>«Максимальное сжатие» берёт самый сильный подход. Он подходит для строгих лимитов, например для загрузки в чат, а не для повседневного использования.</p>\n<p>Пресеты — это начальные точки. После выбора пресета палитру, масштаб и частоту кадров можно настроить отдельно.</p>\n<p>Выбирать «Максимальное сжатие» для красивого GIF — значит тратить его качество. Самый сильный пресет нужен для строгих лимитов, а не для красоты.</p>\n<h2 id=\"colour-palette\">Цветовая палитра</h2>\n<p>GIF хранит максимум 256 цветов на кадр. Уменьшение этого числа — самый быстрый способ уменьшить файл.</p>\n<p>При 128 цветах большинство GIF всё ещё выглядят хорошо. Плоская графика и скринкасты почти не меняются, а фотографии теряют часть плавности.</p>\n<p>Выбирайте палитру под содержимое. Графика терпит маленькие палитры, а фотографиям нужны большие.</p>\n<p>Для скринкастов сжимайте с пресетом «Сбалансированный» и палитрой 128 цветов. Графика интерфейса терпит маленькие палитры, а текст остаётся читаемым.</p>\n<p>Для реакций используйте пресет «Сбалансированный» с палитрой 128 цветов. Реакции обычно фотографические, поэтому им нужна большая палитра, чтобы избежать полос.</p>\n<h2 id=\"frame-rate\">Частота кадров</h2>\n<p>Частота кадров — это сколько кадров воспроизводится в секунду. Плавный GIF идёт при 15 или 30 кадрах в секунду, а дёрганый — при 8 или 10.</p>\n<p>Удаление кадров убирает каждый второй или третий кадр. Анимация становится короче по кадрам, но сохраняет тайминг, поэтому не ускоряется.</p>\n<p>Секрет в том, что GIF сохраняет исходную длительность. Удалённые кадры компенсируются большим временем показа оставшихся кадров.</p>\n<p>Быстрое действие страдает от удаления кадров сильнее всего. Бегущий человек становится дёрганым, а медленное затухание почти не меняется.</p>\n<p>Для записей экрана удаление кадров работает хорошо. Анимации интерфейса достаточно медленные, чтобы половина кадров выглядела плавной.</p>\n<h2 id=\"output-scale\">Масштаб вывода</h2>\n<p>Масштабирование уменьшает размеры каждого кадра в пикселях. При 50 процентах GIF вдвое уже и вдвое ниже, с вчетверо меньшим числом пикселей.</p>\n<p>Масштаб — самый сильный отдельный рычаг. Уменьшение размеров вдвое часто сокращает вес файла больше чем вдвое.</p>\n<p>Подбирайте масштаб под размер показа. GIF, показанный шириной 400 пикселей, должен быть около 400 пикселей в файле.</p>\n<p>Не уменьшайте GIF без нужды: слишком маленький GIF на большом экране выглядит размытым.</p>\n<p>Проверяйте результат в том месте, где GIF будет показываться. Размер показа решает, какой масштаб нужен.</p>\n<h2 id=\"animation-timing\">Тайминг анимации</h2>\n<p>Задержки кадров переносятся и корректируются при удалении кадров. Общая длительность остаётся той же, поэтому анимация не ускоряется.</p>\n<p>Если анимация кажется неправильной, удаление кадров может быть слишком агрессивным. Повторите с меньшим числом удалённых кадров или более мягким пресетом.</p>\n<p>Проверяйте GIF в том чате или на той странице, где он будет использоваться. То, что хорошо играет в одном месте, может иначе выглядеть в другом.</p>\n<p>Длительность анимации важна для восприятия: слишком быстрая анимация раздражает, а слишком медленная — усыпляет.</p>\n<p>Сохраняйте исходную длительность, когда это возможно. Изменение длительности меняет характер анимации.</p>\n<h2 id=\"transparency-gifs\">Прозрачность в GIF</h2>\n<p>GIF поддерживают прозрачность: один полностью прозрачный цвет на кадр. Так стикеры и наложения получают прозрачный фон.</p>\n<p>Уменьшение палитры может сделать прозрачные края грубыми. Мягкая тень вокруг стикера может стать зубчатой при маленькой палитре.</p>\n<p>Для стикеров и наложений держите палитру щедрой. Прозрачность важнее, чем последние килобайты экономии.</p>\n<p>Проверяйте прозрачные края в полном размере. Зубчатые края заметны сразу, когда GIF накладывается на цветной фон.</p>\n<p>Если прозрачность не нужна, не сохраняйте её. Непрозрачный GIF сжимается лучше, чем прозрачный.</p>\n<h2 id=\"discord-slack\">Discord и Slack</h2>\n<p>Платформы чатов ограничивают загрузку GIF, часто до 8 или 10 МБ. GIF, превышающий лимит, просто не отправится.</p>\n<p>Сжатие под лимит — это решение. Пресет «Максимальное сжатие» в большинстве случаев доводит GIF на 20 МБ до лимита.</p>\n<p>Проверьте точный лимит платформы перед сжатием. Бесплатный лимит Discord отличается от платного, а у Slack — свои правила.</p>\n<p>Проверьте GIF в том чате, где он будет использоваться. Реакция, которая хорошо играет в Discord, может иначе выглядеть в Slack.</p>\n<p>Для реакций используйте пресет «Сбалансированный» с палитрой 128 цветов. Это даёт хороший баланс размера и качества для чатов.</p>\n<h2 id=\"gif-vs-video\">GIF против видео</h2>\n<p>Видеофайлы намного меньше для того же ролика. Десятисекундная анимация может весить 15 МБ как GIF и 1,5 МБ как MP4.</p>\n<p>Но GIF играют везде без нажатия кнопки: в чатах, письмах, на страницах. Видео требует плеера и часто — нажатия для запуска.</p>\n<p>Для коротких циклов GIF удобнее: они зацикливаются сами и не требуют управления.</p>\n<p>Для длинных роликов видео выигрывает: разница в весе становится огромной, а GIF теряет смысл.</p>\n<p>Выбирайте по назначению: короткий цикл для чата — GIF, длинный ролик для сайта — видео.</p>\n<h2 id=\"common-mistakes\">Типичные ошибки</h2>\n<p>Выбор «Максимального сжатия» для красивого GIF тратит его качество. Самый сильный пресет нужен для строгих лимитов, а не для повседневного использования.</p>\n<p>Слишком маленькая палитра для фотографического GIF даёт полосы и пятна. Фотографиям нужна большая палитра.</p>\n<p>Слишком агрессивное удаление кадров делает анимацию дёрганой. Быстрое действие страдает от этого сильнее всего.</p>\n<p>Забывать проверять результат — тоже ошибка. Вес файла может быть правильным, а анимация — испорченной.</p>\n<p>И не сжимайте GIF повторно: каждый круг добавляет повреждения, а анимация страдает от этого сильнее, чем фото.</p>\n<h2 id=\"gif-file-anatomy\">Анатомия файла GIF</h2>\n<p>Файл GIF — это последовательность кадров, у каждого из которых своё маленькое изображение и время задержки. Плеер показывает каждый кадр столько, сколько указано в задержке, создавая движение.</p>\n<p>Каждый кадр несёт свою палитру до 256 цветов. Кадры могут делить общую палитру или нести свою, в зависимости от того, как сделан GIF.</p>\n<p>Кадры также несут метод утилизации. Он говорит плееру, оставить ли кадр видимым или очистить его перед показом следующего.</p>\n<p>Понимание анатомии помогает сжимать лучше. Срезы палитры влияют на цвета, удаление кадров — на плавность, а масштаб — на каждый кадр сразу.</p>\n<p>Записывайте, какой пресет сработал и какая палитра подошла. Каждый сжатый GIF чему-то учит.</p>\n<h2 id=\"screen-recordings\">Записи экрана</h2>\n<p>Записывайте с умеренной частотой кадров. Пятнадцать кадров в секунду достаточно плавно для работы с интерфейсом и вдвое меньше тридцати.</p>\n<p>Сжимайте с пресетом «Сбалансированный» и палитрой 128 цветов. Графика интерфейса терпит маленькие палитры, а текст остаётся читаемым.</p>\n<p>Обрезайте запись плотно вокруг нужной области. Пустые края тратят бюджет, который нужен интерфейсу.</p>\n<p>Для записей экрана удаление кадров работает хорошо. Анимации интерфейса достаточно медленные, чтобы половина кадров выглядела плавной.</p>\n<p>Проверьте запись в том месте, где она будет показываться. Текст интерфейса должен оставаться читаемым после сжатия.</p>\n<h2 id=\"reaction-gifs\">GIF-реакции</h2>\n<p>Обрезайте плотно вокруг объекта. Лицо, заполняющее кадр, читается мгновенно, а широкий кадр тратит момент впустую.</p>\n<p>Используйте пресет «Сбалансированный» с палитрой 128 цветов. Реакции обычно фотографические, поэтому им нужна большая палитра, чтобы избежать полос.</p>\n<p>Проверьте GIF в том чате, где он будет использоваться. Реакция, которая хорошо играет в Discord, может иначе выглядеть в Slack.</p>\n<p>Держите реакции короткими: две-три секунды достаточно, чтобы передать эмоцию. Длинные реакции теряют эффект.</p>\n<p>Называйте файлы по содержанию, а не по порядку скачивания. Имя вроде thumbs-up-reaction.gif лучше, чем GIF-4821.gif.</p>\n<h2 id=\"gif-seo\">GIF и SEO</h2>\n<p>GIF на веб-странице — самый тяжёлый элемент, который она может нести. Один GIF на 10 МБ может перевесить все остальные изображения вместе.</p>\n<p>Ограничьте число GIF на странице. Три зацикленные анимации соревнуются за внимание, а один сфокусированный GIF работает лучше.</p>\n<p>Добавляйте описательный alt-текст каждому GIF. Поисковики не видят анимацию, они читают её описание.</p>\n<p>Используйте ленивую загрузку для GIF ниже сгиба. Они не видны при открытии страницы, поэтому браузер может загрузить их позже.</p>\n<p>Рассмотрите видео вместо GIF для длинных анимаций. Видео весит в разы меньше и даёт тот же эффект.</p>\n<h2 id=\"gif-accessibility\">Доступность GIF</h2>\n<p>Мигающие GIF могут вызывать дискомфорт и даже приступы у людей с фоточувствительностью. Избегайте быстрого мигания.</p>\n<p>Добавляйте alt-текст, описывающий анимацию. Пользователи программ чтения с экрана не видят движение, им нужно описание.</p>\n<p>Дайте пользователям способ остановить анимацию, когда это возможно. Зацикленная анимация без паузы раздражает.</p>\n<p>Не полагайтесь только на анимацию для передачи информации. Важное сообщение должно быть и в тексте рядом.</p>\n<p>Уважайте настройки пользователя: многие браузеры позволяют отключить анимацию, и ваш сайт должен работать и без неё.</p>\n<h2 id=\"storing-gifs\">Хранение GIF</h2>\n<p>Храните оригиналы GIF отдельно от сжатых копий. Сжатая копия не превращается обратно в качественный оригинал.</p>\n<p>Называйте файлы по содержанию, а не по порядку скачивания. Имя вроде thumbs-up-reaction.gif лучше, чем GIF-4821.gif.</p>\n<p>Проверяйте сохранённые GIF перед повторным использованием. GIF, хороший в прошлом году, может не подойти под нынешний лимит платформы.</p>\n<p>Никогда не сжимайте повторно используемый GIF. Если нужен новый размер, вернитесь к оригиналу.</p>\n<p>Ведите запись: какой пресет сработал, какая палитра подошла и как изменился вес файла. Каждый GIF чему-то учит.</p>\n<h2 id=\"keep-practising\">Продолжайте практиковаться</h2>\n<p>Каждый сжатый GIF чему-то учит. Запишите, какой пресет сработал, какая палитра подошла содержимому и как изменился вес файла.</p>\n<p>Тестируйте разные пресеты на одном GIF. Сравнение рядом покажет, где проходит граница между качеством и размером.</p>\n<p>Делитесь знаниями с командой. Общая заметка с настройками экономит часы каждому.</p>\n<p>Следите за лимитами платформ: они меняются, и прошлогодние настройки могут не подойти сегодня.</p>\n<p>И помните: лучший GIF — это не самый маленький, а тот, который передаёт идею и при этом загружается быстро.</p>\n<p>Когда готовите GIF для нового проекта, начните с короткого теста: сожмите один файл тремя пресетами и сравните их. Один тест покажет, где проходит граница качества.</p>\n<p>Записывайте, какой пресет сработал для каждого типа GIF. Реакции, записи экрана и анимации для сайта нуждаются в разных настройках.</p>\n<p>Проверяйте GIF в том месте, где он будет использоваться. То, что хорошо играет в Discord, может иначе выглядеть в Slack или на сайте.</p>\n<p>Не забывайте про лимиты платформ: они меняются, и прошлогодние настройки могут не подойти сегодня. Проверяйте лимит перед каждой отправкой.</p>\n<p>Для длинных анимаций рассмотрите видео вместо GIF. Десять секунд как GIF весят в разы больше, чем те же десять секунд как MP4.</p>\n<p>Держите оригиналы GIF в архиве. Если понадобится другой размер или формат, свежая копия с оригинала делается за минуту.</p>\n<p>Называйте файлы по содержанию сразу после скачивания. Имена вроде reaction-laugh.gif найти проще, чем GIF-01.gif.</p>\n<p>Делитесь знаниями с друзьями и командой. Общая заметка с пресетами и палитрами экономит часы каждому.</p>\n<p>Лучший GIF для чата — короткий, лёгкий и понятный без звука. Если ролик длиннее десяти секунд, подумайте о видео вместо GIF.</p>\n<p>Лимиты Discord отличаются для бесплатных и платных аккаунтов: проверьте свой, прежде чем сжимать. GIF должен укладываться именно в ваш лимит.</p>\n<p>Для Slack действуют свои правила: уточните их в справке платформы, а не полагайтесь на память о Discord.</p>\n<p>Обрезка длительности — сильный рычаг: GIF вдвое короче весит почти вдвое меньше. Уберите скучное начало и конец анимации.</p>\n<p>Задержки кадров переносятся автоматически, поэтому обрезанный GIF сохраняет плавность. Общая длительность меняется, а тайминг внутри остаётся естественным.</p>\n<p>Стикеры с прозрачностью требуют щедрой палитры: мягкая тень вокруг стикера при маленькой палитре становится зубчатой.</p>\n<p>Один GIF на 10 МБ на странице перевешивает все остальные изображения вместе. Ограничьте число GIF на странице до одного-двух.</p>\n<p>Добавляйте alt-текст, описывающий анимацию: программы чтения с экрана не видят движение, им нужно описание.</p>\n<p>Чек-лист перед отправкой GIF: вес ниже лимита платформы, анимация играет целиком, края чистые, цикл переходит плавно, имя файла по содержанию.</p>\n<p>Если GIF нужен для сайта, проверьте вес страницы после публикации. Один GIF на 10 МБ перевешивает все остальные изображения вместе.</p>\n<p>Покажите GIF другу, не говоря, что изменилось. Свежий взгляд замечает дёрганность, которую вы перестали видеть.</p>\n<p>В письмах GIF работают там, где видео не работает: почтовые клиенты показывают GIF автоматически, а видео — почти никогда.</p>\n<p>Практические шаги читайте в статье <a href=\"/ru/blog/kak-szhat-gif/\">Как сжать GIF</a>. Сравнение с WebP и MP4 — в статье <a href=\"/ru/blog/gif-webp-mp4-sravnenie-animirovannykh-izobrazheniy/\">GIF, WebP и MP4: сравнение анимированных изображений</a>. Для создания GIF используйте <a href=\"/ru/sozdat-gif/\">создатель GIF</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Изменит ли сжатие GIF скорость его воспроизведения?","answer":"Нет. Задержки кадров переносятся и корректируются при удалении кадров, поэтому общая длительность остаётся той же. Анимация не ускоряется и не замедляется — меняется только число кадров и их качество."},{"question":"Почему мой GIF всё ещё большой после сжатия?","answer":"Потому что GIF — старый формат с ограниченной палитрой, и длинные или детальные анимации сжимаются плохо. Попробуйте пресет «Максимальное сжатие», уменьшите масштаб вдвое или сократите длительность. Если ничего не помогает, рассмотрите видео MP4 вместо GIF."},{"question":"Какую палитру выбрать для фотографического GIF?","answer":"Держите палитру большой — 128 цветов или больше. Фотографические GIF страдают от маленьких палитр сильнее, чем плоская графика: появляются полосы и пятна. Для графики интерфейса хватит и 64–128 цветов."},{"question":"Можно ли сжать GIF под лимиты загрузки Discord?","answer":"Да. Проверьте точный лимит Discord — бесплатный и платный лимиты отличаются — а затем используйте пресет «Максимальное сжатие». В большинстве случаев он доводит GIF на 20 МБ до лимита 8 или 10 МБ."},{"question":"Работает ли компрессор GIF на однокадровых файлах GIF?","answer":"Да, но однокадровый GIF — это по сути обычное изображение. Для него лучше подойдёт обычный компрессор изображений с точным лимитом в килобайтах. Компрессор GIF полезен именно для анимированных файлов с несколькими кадрами."},{"question":"Чем компрессор GIF отличается от создателя GIF?","answer":"Компрессор уменьшает вес готового GIF: палитра, кадры, масштаб. Создатель GIF делает новый GIF из изображений или видео. Если у вас уже есть GIF и он слишком большой — используйте компрессор; если нужно создать анимацию с нуля — создатель."}];
